 74→/** Downloads a pre-filled sample CSV template the user can fill in and import. */
 75→function downloadSampleCsv() {
 76→  const sample = [
 77→    "Zip Code,Zone,Status,Message,ETA,COD,Return Policy",
 78→    "10001,Manhattan,allowed,We deliver here! Estimated 2-3 days.,2-3 days,Yes,30-day returns accepted",
 79→    "90210,Beverly Hills,allowed,Same day delivery available.,1 day,No,",
 80→    "33101,Miami,blocked,Sorry we do not deliver to this area.,,",
 81→  ].join("\n");
 82→  const blob = new Blob([sample], { type: "text/csv" });
 83→  const url = URL.createObjectURL(blob);
 84→  const a = document.createElement("a");
 85→  a.href = url;
 86→  a.download = "sample-zip-codes.csv";
 87→  a.click();
 88→  URL.revokeObjectURL(url);
 89→}
