 91→export const loader = async ({ request }: LoaderFunctionArgs) => {
 92→  const { session } = await authenticate.admin(request);
 93→  const shop = session.shop;
 94→
 95→  const [zipCodes, subscription] = await Promise.all([
 96→    db.zipCode.findMany({
 97→      where: { shop },
 98→      orderBy: { createdAt: "desc" },
 99→    }),
100→    getShopSubscription(shop),

100→    getShopSubscription(shop),
101→  ]);
102→
103→  const stats = {
104→    total: zipCodes.length,
105→    allowed: zipCodes.filter((z) => z.type === "allowed").length,
106→    blocked: zipCodes.filter((z) => z.type === "blocked").length,
107→    active: zipCodes.filter((z) => z.isActive).length,
108→  };
109→
110→  return { zipCodes, stats, subscription };
111→};
