113→export const action = async ({ request }: ActionFunctionArgs) => {
114→  const { session } = await authenticate.admin(request);
115→  const shop = session.shop;
116→  const formData = await request.formData();
117→  const intent = formData.get("intent");
118→
119→  if (intent === "add") {
120→    const zipCode = String(formData.get("zipCode") ?? "").trim().toUpperCase();
121→    const label = String(formData.get("label") || "").trim();
122→    const zone = String(formData.get("zone") || "").trim();
123→    const message = String(formData.get("message") || "").trim();
124→    const eta = String(formData.get("eta") || "").trim();
125→    // Sanitize type — only accept known values, default to "allowed"
126→    const rawType = String(formData.get("type") || "");
127→    const type = rawType === "blocked" ? "blocked" : "allowed";
128→    const codAvailable =
129→      formData.get("codAvailable") === "true"
130→        ? true
131→        : formData.get("codAvailable") === "false"
132→          ? false
133→          : null;
134→    const returnPolicy = (formData.get("returnPolicy") as string | null) || null;
135→
136→    if (!zipCode) return { error: "Zip code is required." };
137→
138→    try {
139→      const subscription = await getShopSubscription(shop);
140→      const limits = PLAN_LIMITS[subscription.planTier];
141→
142→      if (type === "blocked" && !limits.allowBlocked) {
143→        return {
144→          error:
145→            "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
146→          upgradeRequired: true,
147→        };
148→      }
149→
150→      const currentCount = await db.zipCode.count({ where: { shop } });
151→      if (limits.maxZipCodes < UNLIMITED && currentCount >= limits.maxZipCodes) {
152→        const upgradeTarget =
153→          subscription.planTier === "free" ? "Starter" : "Pro";
154→        return {
155→          error: `You have reached the ${limits.maxZipCodes} zip code limit on the ${limits.label} plan. Upgrade to ${upgradeTarget} for a higher limit.`,
156→          upgradeRequired: true,
157→        };
158→      }
159→
160→      await db.zipCode.create({
161→        data: {
162→          shop,
163→          zipCode,
164→          label: label || null,
165→          zone: zone || null,
166→          message: message || null,
167→          eta: eta || null,
168→          type,
169→          codAvailable: codAvailable ?? undefined,
170→          returnPolicy: returnPolicy ?? undefined,
171→        },
172→      });
173→      return { success: true, action: "added", zipCode };
174→    } catch (err) {
175→      // P2002 = unique constraint violation (duplicate zip code)
176→      const code = (err as { code?: string }).code;
177→      if (code === "P2002") {
178→        return { error: `Zip code "${zipCode}" already exists.` };
179→      }
180→      return { error: "Failed to add zip code. Please try again." };
181→    }
182→  }
183→
184→  if (intent === "delete") {
185→    const id = String(formData.get("id") ?? "");
186→    if (!id) return { error: "Missing zip code ID." };
187→    try {
188→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
189→      if (!existing) return { error: "Zip code not found." };
190→      // Delete scoped to both id and shop for defense-in-depth
191→      await db.zipCode.delete({ where: { id: existing.id } });
192→      return { success: true, action: "deleted" };
193→    } catch {
194→      return { error: "Failed to delete zip code." };
195→    }
196→  }
197→
198→  if (intent === "update") {
199→    const id = String(formData.get("id") ?? "");
200→    const zipCode = String(formData.get("zipCode") ?? "").trim().toUpperCase();
201→    const label = String(formData.get("label") || "").trim();
202→    const zone = String(formData.get("zone") || "").trim();
203→    const message = String(formData.get("message") || "").trim();
204→    const eta = String(formData.get("eta") || "").trim();
205→    // Sanitize type — only accept known values, default to "allowed"
206→    const rawType = String(formData.get("type") || "");
207→    const type = rawType === "blocked" ? "blocked" : "allowed";
208→    const isActive = formData.get("isActive") === "true";
209→    const codAvailable =
210→      formData.get("codAvailable") === "true"
211→        ? true
212→        : formData.get("codAvailable") === "false"
213→          ? false
214→          : null;
215→    const returnPolicy = (formData.get("returnPolicy") as string | null) || null;
216→
217→    if (!id) return { error: "Missing zip code ID." };
218→    if (!zipCode) return { error: "Zip code is required." };
219→

220→    try {
221→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
222→      if (!existing) return { error: "Zip code not found." };
223→      // Update scoped to verified id+shop record
224→      await db.zipCode.update({
225→        where: { id: existing.id },
226→        data: {
227→          zipCode,
228→          label: label || null,
229→          zone: zone || null,
230→          message: message || null,
231→          eta: eta || null,
232→          type,
233→          isActive,
234→          codAvailable,
235→          returnPolicy,
236→        },
237→      });
238→      return { success: true, action: "updated", zipCode };
239→    } catch (err) {
240→      const code = (err as { code?: string }).code;
241→      if (code === "P2002") {
242→        return { error: `Zip code "${zipCode}" already exists.` };
243→      }
244→      return { error: `Failed to update zip code "${zipCode}". Please try again.` };
245→    }
246→  }
247→
248→  if (intent === "toggle") {
249→    const id = String(formData.get("id") ?? "");
250→    if (!id) return { error: "Missing zip code ID." };
251→    const isActive = formData.get("isActive") === "true";
252→    try {
253→      const existing = await db.zipCode.findFirst({ where: { id, shop } });
254→      if (!existing) return { error: "Zip code not found." };
255→      // Update scoped to verified id+shop record
256→      await db.zipCode.update({
257→        where: { id: existing.id },
258→        data: { isActive: !isActive },
259→      });
260→      return { success: true, action: "toggled" };
261→    } catch {
262→      return { error: "Failed to toggle zip code status." };
263→    }
264→  }
265→
266→  if (intent === "check") {
267→    const zipCode = String(formData.get("checkZip")).trim().toUpperCase();
268→    try {
269→      const found = await db.zipCode.findUnique({
270→        where: { shop_zipCode: { shop, zipCode } },
271→      });
272→      if (!found) return { checkResult: { found: false, zipCode } };
273→      return { checkResult: { found: true, zipCode, record: found } };
274→    } catch {
275→      return { error: "Failed to check zip code." };
276→    }
277→  }
278→
279→  if (intent === "bulk-import") {
280→    const csvData = String(formData.get("csvData") || "");
281→    if (!csvData.trim()) return { error: "No CSV data provided." };
282→
283→    try {
284→      const subscription = await getShopSubscription(shop);
285→      const limits = PLAN_LIMITS[subscription.planTier];
286→
287→      if (!limits.csvImport) {
288→        const upgradeTarget =
289→          subscription.planTier === "free" ? "Starter" : "Pro";
290→        return {
291→          error: `CSV import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to import zip codes via CSV.`,
292→          upgradeRequired: true,
293→        };
294→      }
295→
296→      const lines = csvData
297→        .split("\n")
298→        .map((l) => l.trim())
299→        .filter((l) => l.length > 0);
300→
301→      // Skip header row if present
302→      const startIdx =
303→        lines.length > 0 &&
304→        lines[0].toLowerCase().includes("zip")
305→          ? 1
306→          : 0;
307→
308→      const currentCount = await db.zipCode.count({ where: { shop } });
309→      let imported = 0;
310→      let skipped = 0;
311→      const errors: string[] = [];
312→
313→      for (let i = startIdx; i < lines.length; i++) {
314→        const cols = parseCsvRow(lines[i]);
315→        const zipCode = (cols[0] || "").toUpperCase().trim();
316→        if (!zipCode) continue;
317→
318→        const zone = cols[1] || null;
319→        // Sanitize: only "blocked" is accepted as an alternative to "allowed"
320→        const type = (cols[2] || "").toLowerCase().trim() === "blocked" ? "blocked" : "allowed";
321→        const message = cols[3] || null;
322→        const eta = cols[4] || null;
323→        const codRaw = (cols[5] || "").toLowerCase().trim();
324→        const codAvailable =
325→          codRaw === "yes" || codRaw === "true"
326→            ? true
327→            : codRaw === "no" || codRaw === "false"
328→              ? false
329→              : null;
330→        const returnPolicy = cols[6] || null;
331→
332→        if (type === "blocked" && !limits.allowBlocked) {
333→          skipped++;
334→          continue;
335→        }
336→
337→        if (
338→          limits.maxZipCodes < UNLIMITED &&
339→          currentCount + imported >= limits.maxZipCodes

340→        ) {
341→          const upgradeTarget =
342→            subscription.planTier === "free" ? "Starter" : "Pro";
343→          errors.push(
344→            `Reached the ${limits.maxZipCodes} zip code limit on the ${limits.label} plan. Upgrade to ${upgradeTarget} for a higher limit. ${lines.length - startIdx - imported - skipped} zip codes were not imported.`,
345→          );
346→          break;
347→        }
348→
349→        try {
350→          await db.zipCode.upsert({
351→            where: { shop_zipCode: { shop, zipCode } },
352→            create: {
353→              shop,
354→              zipCode,
355→              zone,
356→              type,
357→              message,
358→              eta,
359→              codAvailable,
360→              returnPolicy,
361→            },
362→            update: {
363→              zone: zone ?? undefined,
364→              type,
365→              message: message ?? undefined,
366→              eta: eta ?? undefined,
367→              codAvailable,
368→              returnPolicy: returnPolicy ?? undefined,
369→            },
370→          });
371→          imported++;
372→        } catch {
373→          skipped++;
374→        }
375→      }
376→
377→      return {
378→        success: true,
379→        action: "bulk-import",
380→        imported,
381→        skipped,
382→        errors,
383→      };
384→    } catch {
385→      return { error: "Failed to import zip codes. Please try again." };
386→    }
387→  }
388→
389→  if (intent === "export") {
390→    try {
391→      const subscription = await getShopSubscription(shop);
392→      const limits = PLAN_LIMITS[subscription.planTier];
393→
394→      if (!limits.csvExport) {
395→        return {
396→          error: `CSV export is not available on the ${limits.label} plan. Upgrade to Pro or Ultimate to export your zip codes.`,
397→          upgradeRequired: true,
398→        };
399→      }
400→
401→      const zipCodes = await db.zipCode.findMany({
402→        where: { shop },
403→        orderBy: { createdAt: "desc" },
404→      });
405→
406→      const header = "Zip Code,Zone,Status,Message,ETA,Active,COD,Return Policy";
407→      const rows = zipCodes.map(
408→        (z) =>
409→          `"${z.zipCode}","${z.zone || ""}","${z.type}","${z.message || ""}","${z.eta || ""}","${z.isActive ? "Yes" : "No"}","${z.codAvailable === true ? "Yes" : z.codAvailable === false ? "No" : ""}","${z.returnPolicy || ""}"`,
410→      );
411→      const csv = [header, ...rows].join("\n");
412→
413→      return { success: true, action: "export", csv };
414→    } catch {
415→      return { error: "Failed to export zip codes." };
416→    }
417→  }
418→
419→  if (intent === "bulk-delete") {
420→    const idsRaw = String(formData.get("ids") || "");
421→    const ids = idsRaw
422→      .split(",")
423→      .map((id) => id.trim())
424→      .filter(Boolean);
425→
426→    if (ids.length === 0) return { error: "No zip codes selected." };
427→
428→    // Guard: cap to a reasonable max to prevent abuse
429→    if (ids.length > 5000) {
430→      return { error: "Too many zip codes selected at once. Please select fewer than 5000." };
431→    }
432→
433→    try {
434→      // Delete only records that belong to this shop — always shop-scoped.
435→      // We do NOT reject if some IDs are missing (race condition / already deleted)
436→      // — instead we report how many were actually deleted.
437→      const result = await db.zipCode.deleteMany({
438→        where: { id: { in: ids }, shop },
439→      });
440→      return { success: true, action: "bulk-delete", deleted: result.count };
441→    } catch {
442→      return { error: "Failed to delete selected zip codes." };
443→    }
444→  }
445→
446→  if (intent === "range-import") {
447→    const startZip = String(formData.get("startZip") || "").trim().toUpperCase();
448→    const endZip = String(formData.get("endZip") || "").trim().toUpperCase();
449→    const zone = (formData.get("zone") as string | null) || null;
450→    // Sanitize type — only accept known values, default to "allowed"
451→    const type = String(formData.get("type") || "") === "blocked" ? "blocked" : "allowed";
452→    const message = (formData.get("message") as string | null) || null;
453→    const eta = (formData.get("eta") as string | null) || null;
454→
455→    // Validate: must be 5-digit numeric zips
456→    const ZIP_RE = /^\d{5}$/;
457→    if (!ZIP_RE.test(startZip) || !ZIP_RE.test(endZip)) {
458→      return { error: "ZIP range import only supports 5-digit US ZIP codes (e.g., 10001)." };
459→    }

460→
461→    const start = parseInt(startZip, 10);
462→    const end = parseInt(endZip, 10);
463→
464→    if (end < start) {
465→      return { error: "End ZIP must be greater than or equal to Start ZIP." };
466→    }
467→
468→    const rangeSize = end - start + 1;
469→    const MAX_RANGE = 500;
470→    if (rangeSize > MAX_RANGE) {
471→      return { error: `Range too large. Maximum ${MAX_RANGE} zip codes per import (got ${rangeSize}).` };
472→    }
473→
474→    try {
475→      // Check plan limits
476→      const subscription = await getShopSubscription(shop);
477→      const limits = PLAN_LIMITS[subscription.planTier];
478→
479→      if (!limits.csvImport) {
480→        const upgradeTarget =
481→          subscription.planTier === "free" ? "Starter" : "Pro";
482→        return {
483→          error: `ZIP range import is not available on the ${limits.label} plan. Upgrade to ${upgradeTarget} to use bulk import features.`,
484→          upgradeRequired: true,
485→        };
486→      }
487→
488→      if (type === "blocked" && !limits.allowBlocked) {
489→        return {
490→          error: "Blocked zip codes are not available on your current plan. Upgrade to Pro or Ultimate to use blocked zip codes.",
491→          upgradeRequired: true,
492→        };
493→      }
494→
495→      const currentCount = await db.zipCode.count({ where: { shop } });
496→      if (limits.maxZipCodes < UNLIMITED && currentCount + rangeSize > limits.maxZipCodes) {
497→        const upgradeTarget =
498→          subscription.planTier === "free" ? "Starter" : "Pro";
499→        return {
500→          error: `This range would exceed your ${limits.label} plan limit of ${limits.maxZipCodes} zip codes. You have ${limits.maxZipCodes - currentCount} slots remaining. Upgrade to ${upgradeTarget} for a higher limit.`,
501→          upgradeRequired: true,
502→        };
503→      }
504→
505→      // Build all zip records for the range
506→      const zipRecords = Array.from({ length: rangeSize }, (_, i) => ({
507→        shop,
508→        zipCode: String(start + i).padStart(5, "0"),
509→        zone: zone ?? undefined,
510→        type,
511→        message: message ?? undefined,
512→        eta: eta ?? undefined,
513→      }));
514→
515→      // Use createMany with skipDuplicates — much faster than N sequential upserts.
516→      // For existing records (skipDuplicates), we do a follow-up updateMany to refresh
517→      // zone/type/message/eta so the import always reflects the submitted values.
518→      const created = await db.zipCode.createMany({
519→        data: zipRecords,
520→        skipDuplicates: true,
521→      });
522→
523→      // Update any already-existing records in the range to apply the new values
524→      await db.zipCode.updateMany({
525→        where: {
526→          shop,
527→          zipCode: { in: zipRecords.map((r) => r.zipCode) },
528→        },
529→        data: {
530→          zone: zone ?? undefined,
531→          type,
532→          message: message ?? undefined,
533→          eta: eta ?? undefined,
534→        },
535→      });
536→
537→      return { success: true, action: "range-import", imported: created.count, total: rangeSize };
538→    } catch {
539→      return { error: "Failed to import ZIP code range. Please try again." };
540→    }
541→  }
542→
543→  // Unknown intent
544→  return { error: "Unknown action." };
545→};
