 35→// Skeleton shown during page-to-page navigation transitions inside the app shell.
 36→// useNavigation must be called inside PolarisAppProvider so Polaris context is available.
 37→function AppContent() {
 38→  const navigation = useNavigation();
 39→  const isNavigating = navigation.state === "loading";
 40→
 41→  if (isNavigating) {
 42→    return (
 43→      <SkeletonPage primaryAction>
