 80→    const BASE_URL = "https://app.chatwoot.com";
 81→    const script = document.createElement("script");
 82→    script.src = `${BASE_URL}/packs/js/sdk.js`;
 83→    script.async = true;
 84→    script.onload = () => {
 85→      window.chatwootSDK?.run({
 86→        websiteToken: "F2gCECkLD25SAkJ92AcVui4x",
 87→        baseUrl: BASE_URL,
 88→      });
 89→    };
 90→    document.body.appendChild(script);
 91→  }, []);
 92→
 93→  return null;
